<?php require 'config.php'; role(['admin']); if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$conn->query("DELETE FROM categories WHERE id=$id");header('Location:categories.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']);if($id){$s=$conn->prepare("UPDATE categories SET name=? WHERE id=?");$s->bind_param('si',$name,$id);}else{$s=$conn->prepare("INSERT INTO categories(name) VALUES(?)");$s->bind_param('s',$name);} $s->execute();header('Location:categories.php');exit;}$edit=null;if(isset($_GET['edit']))$edit=$conn->query("SELECT * FROM categories WHERE id=".(int)$_GET['edit'])->fetch_assoc();$cats=$conn->query("SELECT * FROM categories ORDER BY id DESC");include 'partials/header.php';?><div class="mb-3"><div class="section-title">Kategori Menu</div><div class="sub">Atur kelompok menu agar kasir lebih mudah mencari produk.</div></div><div class="row g-3"><div class="col-lg-4"><div class="cardx p-3"><h5><?=$edit?'Edit':'Tambah'?> Kategori</h5><form method="post" class="mt-3"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><input name="name" class="form-control mb-3" placeholder="Contoh: Makanan" value="<?=htmlspecialchars($edit['name']??'')?>" required><button class="btn btn-primary w-100">Simpan Kategori</button><?php if($edit):?><a href="categories.php" class="btn btn-light w-100 mt-2">Batal</a><?php endif;?></form></div></div><div class="col-lg-8"><div class="cardx"><div class="card-head"><div><h5>Daftar Kategori</h5><small>Kategori yang tersimpan</small></div></div><div class="table-responsive p-2"><table class="table mb-0"><thead><tr><th>KATEGORI</th><th class="text-end">AKSI</th></tr></thead><tbody><?php while($c=$cats->fetch_assoc()):?><tr><td><b><?=htmlspecialchars($c['name'])?></b></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$c['id']?>"><i class="bi bi-pencil"></i></a> <a class="btn btn-sm btn-outline-danger" href="?delete=<?=$c['id']?>" onclick="return confirm('Hapus kategori?')"><i class="bi bi-trash"></i></a></td></tr><?php endwhile;?></tbody></table></div></div></div></div><?php include 'partials/footer.php';?>